mapper.select:
SELECT 
  userId,
  mode,
  CAST(CAST(
      TRUNCATE(MAX(summarySeq) / ${longtermSize}, 0) AS UNSIGNED
    ) * ${longtermSize} AS VARCHAR (10)
  ) AS lastSeq 
FROM
  DOGPOO_AI_CHATBOT_SUMMARY
GROUP BY userId, mode
HAVING CAST(
    TRUNCATE(MAX(summarySeq) / ${longtermSize}, 0) AS UNSIGNED
  ) * ${longtermSize} > 0 ;
